from pathlib import Path
import json
P=Path(__file__).resolve().parent;e=json.loads((P/'edits.json').read_text());n=json.loads((P/'notes.json').read_text())
def p(k,t):e[f'A0558-B{k:04d}']=t
for k in list(e):
 if k.startswith('A0554-'):e[k]=e[k].replace('洛加','珞珈')
p(2,'怀言者原名“帝国传道者”，又称“圣像破坏者”，是最初二十个星际战士军团中的第十七军团。在背叛帝皇的九个军团中，他们最先堕落，成为已知最早的混沌星际战士，效忠于原体珞珈与混沌无分。')
p(16,'配色：深红色配枪铁色镶边（叛乱后）；灰色（叛乱前）。')
p(18,'专长：恶魔巫术、黑暗使徒；合成兵种作战与驻防（叛乱前）。')
p(20,'战吼：选自圣典、切合当下情境的经文，以及悲怆的咆哮。')
p(41,'怀言者早在皈依混沌之前，就以极端的宗教狂热闻名。如今，他们是最狂热的混沌星际战士之一，常由黑暗使徒——堕落的星际战士教士——在战场上鼓舞麾下战士与邪教徒盟军。')
p(45,'如同其他原体，珞珈在婴儿时期便已失散。第十七军团自创立之初，职责与精神面貌便有别于其他阿斯塔特军团：他们作战时全心奉献，狂热无比。最早的新兵来自战败敌人的子嗣，自幼就被教导父辈的罪行，以及获得帝皇宽恕所需付出的代价。因此，其他军团怀着正义感出征，第十七军团却怀着唯有曾被定罪、又获救赎者才能体会的冷酷愤怒。其他军团经过一段时间才获得正式名称，第十七军团却几乎一成立就被称作“帝国传道者”。这是因为他们早期负责传达帝皇的最后通牒：一名身披黑甲、头戴骷髅面盔、手持翼饰钉头锤的使者，孤身前来宣告——臣服，或毁灭。')
p(49,'击败敌人后，帝国传道者会清查其图书馆与档案，剔除一切被认定涉及异端或巫术的内容。遭到判罪的著作、人物与建筑，都以帝国真理之名被抹除。统一战争期间，他们在泰拉各地反复执行这种清洗，由此在帝国中得到一个鲜有人公开提起的绰号：“圣像破坏者”。')
p(52,'帝皇最终在封建世界科尔基斯找到了珞珈。为迎接幻象中预示的帝皇降临，珞珈已发动一连串残酷的宗教战争，将星球统一。当帝皇如预言般到来时，珞珈跪地迎接，带领全体民众欢庆，并将他当作神明膜拜。庆典结束后，帝皇命珞珈带上最优秀的战士，加入以他为原体的星际战士军团——当时的帝国传道者——共同投身大远征。珞珈任命可信赖的摄政者治理科尔基斯，虔诚地遵从父亲的指示。')
p(56,'珞珈是一位异乎寻常地虔诚的原体。其他军团迅速征服一个又一个星球时，怀言者的进展却慢得多：每征服一地，他们都要兴建神殿与圣所，膜拜被珞珈尊为帝国之神的帝皇。凡是被视为威胁帝皇疆域的亵渎与异端，无论古卷、书籍、艺术品还是圣像，都在军团的推进中遭到焚毁、砸碎。在拒绝皈依者堆积如山的尸骸上，他们修建宏伟纪念碑与大教堂，尽数献给帝皇。军团最杰出的教士撰写大量著作，宣扬帝皇的神性与正义；珞珈本人则以无数演说和布道，仅凭言语就使数百万人皈依。')
p(61,'尽管怀言者已投身大远征近一个世纪，帝皇从未因其狂热崇拜而斥责珞珈或军团，即使这套教义与帝国真理相悖。然而，伊斯塔万五号事件发生前四十三年，帝皇终于向怀言者降下怒火。他命极限战士彻底摧毁库尔的首都摩纳齐亚——这座完美之城，凝聚了珞珈与怀言者的一切信念与追求。整个军团被召集到废墟中，接受帝皇、罗伯特·基里曼与掌印者马卡多的训斥。他们被迫跪在自己最伟大成就的灰烬里，再次向帝皇与大远征宣誓效忠。')
p(63,'渐渐地，珞珈认识到，将帝皇奉为神明的信仰是错误的。但他仍坚信，信仰是人类心灵的核心，而自己的观念仍有可能得到证实。他首先转向母星的旧信仰：在被帝皇寻回之前，他曾笃信帝皇就是神，因而在“第一次兄弟会清洗”中摧毁了这些古老信仰。如今，他重返科尔基斯，急切地寻找答案，并向原体中最睿智的赤红马格努斯求教。')
p(66,'在艾瑞巴斯与科尔·法伦的鼓动下——两人其实早已崇拜毁灭诸神——珞珈认定，银河系无数人类文化的信仰体系拥有共同起源，也传递着同一条深层信息。各异文化的无数神话，都提及帷幕之外存在其他力量；他因此相信，人类最本能的信仰冲动不可能全然虚假。于是，他踏上“朝圣之旅”，前往神话中凡人与诸神相会之地，企图发现宇宙普遍的真理，并以此启迪人类，乃至自己的父亲。')
p(70,'怀言者重返大远征，以征战掩护朝圣，分散至群星之间。在大远征的最后五十年里，他们使之归顺的世界，比任何其他军团都多。珞珈随第一千三百零一远征舰队来到卡迪亚，并在那里找到了他所认定的证据：银河各地的旧信仰具有相近起源，因此蕴含共同真理。卡迪亚当地人英格泰尔被诸神选为向导，负责向珞珈揭示“原初真理”。她为此接受仪式，升格为恶魔“升天者英格泰尔”。')
p(72,'升天者英格泰尔率领怀言者的锯齿烈阳战团进入大眼，即恐惧之眼，亲眼见证灵族帝国覆亡的遗迹。她告诉怀言者，灵族之所以失败并遭受陨落，是因为在升华之际无法接受原初真理。他们孕育了掌管欢愉、许诺恩赐的新神，却没有因此喜悦；新神醒来后，发现崇拜者因无知和恐惧背弃自己，于是大眼的无尽风暴形成，成为祂诞生啼哭的回响。在灵族帝国的灰烬中，怀言者听取了这套关于原初真理的启示，并相信：若想让人类存续，就不能重蹈灵族覆辙，而必须拥抱混沌。')
p(74,'朝圣之旅最终使怀言者确信，帝国真理实为谎言，诸神确实存在。他们秘密向新的黑暗诸神宣誓效忠，此后四十年始终掩藏真实立场。为此，军团暗中清洗内部忠诚派，其中大多是仍记得帝国传道者时代的老兵。清洗大体成功，只有少数忠诚派因在大远征末期远赴他处执行任务而幸免。')
p(76,'在大远征余下的岁月中，珞珈与怀言者试图向人类传播他们所信奉的宇宙真理，并逐步将人手派往其他阿斯塔特军团，建立战士结社，从内部实施颠覆。通过这套隐秘手段，他们最终说服数位原体加入自己的事业，其中最关键的便是荷鲁斯·卢佩卡尔。与此同时，怀言者以忠诚之姿接连发动战役，掩人耳目，很快成为大远征中战功最显赫的军团之一，仿佛在弥补昔日过失。珞珈统率这支规模仅次于极限战士的第二大军团，对主要由人类组成的诸帝国发动战争，手段日益凶狠残暴，甚至带着泄愤意味，或许是为了宣泄军团隐忍的屈辱与怨愤。')
p(78,'珞珈与艾瑞巴斯最终认定，只要人类仍受帝皇的谎言束缚，就不可能在不流血的情况下得到启蒙。于是，两人参与策划了荷鲁斯的堕落，掀起荷鲁斯之乱。')
p(79,'The Horus Heresy 荷鲁斯之乱')
p(81,'伊斯塔万五号的登陆点大屠杀后，怀言者彻底撕下忠诚的伪装。他们公开宣扬原初真理，将护甲涂成深红色，并投入被称为“受祝之子”的恶魔化星际战士。荷鲁斯之乱期间，军团估计约有十五万名作战人员。')
p(83,'Possessed Word Bearers battle the Adeptus Custodes during the Horus Heresy 荷鲁斯之乱期间，附魔怀言者与禁军交战')
p(86,'叛乱爆发后，怀言者战舰狂怒深渊号刚在木星卫星图勒建成，便启程前往奥特拉玛。它击毁的第一艘战舰，是正在前往范吉利斯太空港维修的极限战士舰船马库拉格之拳号。遇袭舰上的星语者成功发出警报，范吉利斯太空港收到的却是一声极其强烈的灵能尖啸。极限战士舰队指挥官塞斯图斯连长看见马库拉格及即将降临的恐怖景象，立即在范吉利斯的主要枢纽科拉利斯集结舰船。原文称他找到了七艘：被他征用为指挥舰的愤怒号及其护航舰，以及无畏号、菲洛克斯号、凶猛号、火刃号和千子的残月号。无限号的沃尔沃舰长也请求加入，得到批准。舰队追击狂怒深渊号，与之交战后损失惨重，只剩愤怒号和火刃号。狂怒深渊号随后跃入亚空间，继续驶向奥特拉玛，两舰紧追而入。然而，狂怒深渊号布下一枚灵能水雷，扰乱亚空间，使火刃号的盖勒力场失效，整艘舰船被非物质界的力量撕碎。')
p(88,'怀言者向极限战士发动进攻时，珞珈麾下最出众的勇将、前信仰之主科尔·法伦，负责突袭考斯。他发誓彻底毁灭这颗星球，并几乎得逞。坐镇已更名为伪帝号的私人战斗驳船，他指挥部队全面入侵考斯星系。考斯的三颗姊妹行星遭到大规模地核核打击，自核心崩解；原本温和的恒星也被注入致命金属与其他物质，辐射输出增至十倍。荷鲁斯之乱结束后不到一个世纪，考斯残存的大气便被烧蚀殆尽，地表再无空气，居民被迫迁入巨大的地下洞窟。')
p(92,'考斯之战惨烈而恐怖。怀言者驱使数百万邪教徒充当肉盾，令极限战士震惊；他们释放的恶魔群，也让忠诚战士深感憎恶。但怀言者同样低估了敌人的韧性与决心。最终，马库拉格援军将怀言者逐出考斯地表，科尔·法伦败退。他一路逃往大漩涡——那里星域动荡，混沌的非物质界渗入现实宇宙。与此同时，珞珈与吞世者共同发动暗影远征，企图制造巨大的亚空间风暴，将奥特拉玛与泰拉隔绝。')
p(94,'暗影远征结束后，怀言者奉命在乌兰诺集结，准备随荷鲁斯进攻泰拉。此时，珞珈认为荷鲁斯拒绝彻底投入诸神怀抱，足见其软弱，因而密谋夺取战帅之位。他与扎度·拉亚克率一支小部队进入网道，以召回福格瑞姆参战为名寻找对方，随后用真名成功将其束缚，打算利用他发动政变，推翻荷鲁斯。然而，密谋最终败露，计划破产。荷鲁斯放逐了珞珈，不许他再现身面前；扎度·拉亚克麾下的五千名怀言者却同意继续追随战帅，进军泰拉。与此同时，银河各处仍有少量分散的忠诚派怀言者，为帝皇奋战。')
p(96,'珞珈与拉亚克分道扬镳之际，泽达克·莫达卡尔率领另一支怀言者部队，协助荷鲁斯之子收复母星。')
p(99,'拉亚克麾下的怀言者参加了泰拉围城。荷鲁斯最终战败，混沌军团被迫撤退。不久，怀言者又在“苦难战争”中败北，母星科尔基斯遭到摧毁。他们也被逐入恐惧之眼，此后一直盘踞其间，不时重返帝国，发动袭击、劫掠与破坏。')
n.update({'A0558-B0016':'gunmetal 此处是深灰金属色，译枪铁色；原译炮铜易让人误认铜色。','A0558-B0061':'英文近百年投身远征的主语是怀言者，原译错误改为帝皇一直承诺参加远征。','A0558-B0063':'被珞珈在早期清洗中摧毁的是母星旧信仰，原译句法错位，误称他摧毁帝皇。','A0558-B0070':'as a front 指以大远征为掩护，不是朝圣的前线。','A0558-B0072':'灵族陨落的因果解读是恶魔英格泰尔向怀言者传授的说法，保留叙述归属，不提升为中立旁白认定。','A0558-B0086':'原文称最初有七艘，却只列出六个明确舰名并另提护航舰；随后又加入无限号。保留原数量与列举，不自行补造舰名。','A0558-B0088':'increased tenfold 指变为原来的十倍，不是增加十倍后成为十一倍；人数和数量单位另已按英文修正。','A0558-B0099':'Bitter War 为战役专名，暂译苦难战争，原译苦战遗漏专名性质。'})
for fn,obj in [('edits.json',e),('notes.json',n)]:(P/fn).write_text(json.dumps(obj,ensure_ascii=False,indent=2))
(P/'partial_progress.json').write_text(json.dumps({'article':558,'read_through_block':100,'complete':False},ensure_ascii=False,indent=2))
